def profile_key(action, loaded):
    u = [float(action.get(k,0.)) for k in AXES]
    if sum(v!=0 for v in u)!=1:
        raise ValueError('calibrated motion requires one axis')
    axis = int(np.argmax(np.abs(u)))
    return f"{int(loaded)}:{AXES[axis]}:{u[axis]:.2f}:{float(action['duration_s']):.2f}"

def response(profile, t):
    curve=np.asarray(profile['mean_curve'])
    return np.array([np.interp(t,profile['times'],curve[:,i]) for i in range(3)])

class CloudOdometry:
    """Command facade: one mean drive integrator propagates every own hypothesis."""
    def __init__(self, owner, start_time, profiles):
        self.owner = owner
        self.driver = V7CommandOdometry(start_time, profiles)
        self.driver.step_callback = owner.propagate

    def __getattr__(self, name):
        return getattr(self.driver, name)

    @property
    def pose(self):
        return tuple(float(x) for x in self.owner.poses[self.owner.best])

    @property
    def covariance(self):
        w = self.owner.weights
        p = self.owner.poses.copy()
        yaw = math.atan2(w@np.sin(p[:, 2]), w@np.cos(p[:, 2]))
        p[:, 2] = wrap(p[:, 2]-yaw)
        center = w@p
        delta = p-center
        return (delta.T*w)@delta+np.einsum('n,nij->ij', w, self.owner.pending_cov)

    def advance(self, t):
        self.driver.advance(t)
        return self.pose

    def command(self, row):
        self.driver.command(row)

def motion_variance(delta):
    """OpenSLAM motionmodel.cpp:25-35; ROS defaults:224-239, no GT fit."""
    x, y, theta = np.abs(delta)
    return np.square([.1*x+.1*theta+.03*y, .1*y+.1*theta+.03*x,
                      .2*theta+.2*math.hypot(x, y)])

def _command_propagate(self, delta, ignored_v122_variance):
    # Mean / F Jacobian at .05s integration steps; do not double-count v122 Q.
    RaoBlackwellizedGrid.propagate(self, delta, np.zeros(3))
